        }

        BigDecimal unionMin = a.getMinBudget().min(b.getMinBudget());
        BigDecimal unionMax = a.getMaxBudget().max(b.getMaxBudget());
        BigDecimal overlapRange = overlapMax.subtract(overlapMin);
