        if (unionRange.compareTo(BigDecimal.ZERO) == 0) {
            return 1;
        }
        return overlapRange.divide(unionRange, 4, RoundingMode.HALF_UP).doubleValue();
    }

    private double preferenceCompatibility(Preference source, Preference candidate) {
        int points = 0;
