import { Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { Subscription } from 'rxjs';
import { MatSelectChange } from '@angular/material/select';
import { CityLocation, ResolvedLocation } from '../../models/location.model';
import { LocationService } from '../../services/location.service';
import { LocationStateService } from '../../services/location-state.service';

@Component({
  selector: 'app-location-picker',
  templateUrl: './location-picker.component.html',
  styleUrls: ['./location-picker.component.css']
})
export class LocationPickerComponent implements OnInit, OnDestroy {

  @Output() locationSelected = new EventEmitter<ResolvedLocation | null>();

  cities: CityLocation[] = [];
  loadingCities = true;

  /** Currently resolved location (null = cleared). */
  resolved: ResolvedLocation | null = null;
  geoLoading = false;
  geoError: string | null = null;

  /** True while reverse-geocoding address is being resolved. */
  addressLoading = false;

  private sub: Subscription | null = null;
  private geocodeSub: Subscription | null = null;

  constructor(
    private readonly locationService: LocationService,
    private readonly locationState: LocationStateService
  ) {}

  ngOnInit(): void {
    this.locationService.getCities().subscribe({
      next: (cities) => {
        this.cities = cities;
        this.loadingCities = false;
      },
      error: () => {
        this.loadingCities = false;
      }
    });

    // Restore persisted location from localStorage (if any)
    const persisted = this.locationState.current;
    if (persisted) {
      this.resolved = persisted;
      this.locationSelected.emit(persisted);
    }
  }

  ngOnDestroy(): void {
    this.sub?.unsubscribe();
    this.geocodeSub?.unsubscribe();
  }

  // ── Actions ─────────────────────────────────────────────────────────

  /**
   * Uses the service's getCurrentLocation() which fetches GPS coordinates
   * and automatically enriches with reverse-geocoded address in one call.
   */
  useMyLocation(): void {
    this.sub?.unsubscribe();
    this.geoLoading = true;
    this.addressLoading = true;
    this.geoError = null;

    this.sub = this.locationService.getCurrentLocation().subscribe({
      next: (loc) => {
        this.resolved = loc;
        this.geoLoading = false;
        this.addressLoading = false;
        this.locationState.set(loc);
        this.locationSelected.emit(loc);
      },
      error: (err) => {
        this.geoError = typeof err === 'string' ? err : 'Failed to get location.';
        this.geoLoading = false;
        this.addressLoading = false;
      }
    });
  }

  onCityChange(event: MatSelectChange): void {
    const cityId = Number(event.value);

    if (!cityId) {
      this.clearLocation();
      return;
    }

    const city = this.cities.find((c) => c.id === cityId);
    if (city) {
      const loc: ResolvedLocation = { latitude: city.lat, longitude: city.lng, label: city.name };
      this.geoError = null;
      this.resolveAddress(loc);
    }
  }

  clearLocation(): void {
    this.geocodeSub?.unsubscribe();
    this.resolved = null;
    this.geoError = null;
    this.addressLoading = false;
    this.locationState.clear();
    this.locationSelected.emit(null);
  }

  // ── Private ─────────────────────────────────────────────────────────

  /**
   * For city selections: emit immediately with raw coords, then enrich
   * with address via the service's resolveLocationWithAddress().
   */
  private resolveAddress(loc: ResolvedLocation): void {
    // Emit immediately so consumers get lat/lng fast
    this.resolved = loc;
    this.locationState.set(loc);
    this.locationSelected.emit(this.resolved);

    // Enrich with address via service
    this.geocodeSub?.unsubscribe();
    this.addressLoading = true;

    this.geocodeSub = this.locationService
      .resolveLocationWithAddress(loc)
      .subscribe({
        next: (enriched) => {
          this.resolved = enriched;
          this.addressLoading = false;
          this.locationState.set(enriched);
          this.locationSelected.emit(this.resolved);
        },
        error: () => {
          // Address resolution failed — keep the original label
          this.addressLoading = false;
        }
      });
  }
}

import { Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { Subscription } from 'rxjs';
import { MatSelectChange } from '@angular/material/select';
import { CityLocation, ResolvedLocation } from '../../models/location.model';
import { LocationService } from '../../services/location.service';
import { LocationStateService } from '../../services/location-state.service';

@Component({
  selector: 'app-location-picker',
  templateUrl: './location-picker.component.html',
  styleUrls: ['./location-picker.component.css']
})
export class LocationPickerComponent implements OnInit, OnDestroy {

  /**
   * Scoping key for localStorage persistence.
   * Each module should pass a unique key (e.g. 'pg_location', 'tenant_location')
   * so that selecting a location in PG does NOT affect Tenant and vice-versa.
   */
  @Input() storageKey = 'staymatch_location';

  @Output() locationSelected = new EventEmitter<ResolvedLocation | null>();

  cities: CityLocation[] = [];
  loadingCities = true;

  /** Currently resolved location (null = cleared). */
  resolved: ResolvedLocation | null = null;
  geoLoading = false;
  geoError: string | null = null;

  /** True while reverse-geocoding address is being resolved. */
  addressLoading = false;

  private sub: Subscription | null = null;
  private geocodeSub: Subscription | null = null;

  /** Scoped state instance — created per storageKey. */
  private locationState!: LocationStateService;

  constructor(
    private readonly locationService: LocationService
  ) {}

  ngOnInit(): void {
    // Create a scoped state instance bound to this picker's storageKey
    this.locationState = new LocationStateService(this.storageKey);

    this.locationService.getCities().subscribe({
      next: (cities) => {
        this.cities = cities;
        this.loadingCities = false;
      },
      error: () => {
        this.loadingCities = false;
      }
    });

    // Restore persisted location from localStorage (scoped by storageKey)
    const persisted = this.locationState.current;
    if (persisted) {
      this.resolved = persisted;
      this.locationSelected.emit(persisted);
    }
  }

  ngOnDestroy(): void {
    this.sub?.unsubscribe();
    this.geocodeSub?.unsubscribe();
  }

  // ── Actions ─────────────────────────────────────────────────────────

  /**
   * Uses the service's getCurrentLocation() which fetches GPS coordinates
   * and automatically enriches with reverse-geocoded address in one call.
   */
  useMyLocation(): void {
    this.sub?.unsubscribe();
    this.geoLoading = true;
    this.addressLoading = true;
    this.geoError = null;

    this.sub = this.locationService.getCurrentLocation().subscribe({
      next: (loc) => {
        this.resolved = loc;
        this.geoLoading = false;
        this.addressLoading = false;
        this.locationState.set(loc);
        this.locationSelected.emit(loc);
      },
      error: (err) => {
        this.geoError = typeof err === 'string' ? err : 'Failed to get location.';
        this.geoLoading = false;
        this.addressLoading = false;
      }
    });
  }

  onCityChange(event: MatSelectChange): void {
    const cityId = Number(event.value);

    if (!cityId) {
      this.clearLocation();
      return;
    }

    const city = this.cities.find((c) => c.id === cityId);
    if (city) {
      const loc: ResolvedLocation = { latitude: city.lat, longitude: city.lng, label: city.name };
      this.geoError = null;
      this.resolveAddress(loc);
    }
  }

  clearLocation(): void {
    this.geocodeSub?.unsubscribe();
    this.resolved = null;
    this.geoError = null;
    this.addressLoading = false;
    this.locationState.clear();
    this.locationSelected.emit(null);
  }

  // ── Private ─────────────────────────────────────────────────────────

  /**
   * For city selections: emit immediately with raw coords, then enrich
   * with address via the service's resolveLocationWithAddress().
   */
  private resolveAddress(loc: ResolvedLocation): void {
    // Emit immediately so consumers get lat/lng fast
    this.resolved = loc;
    this.locationState.set(loc);
    this.locationSelected.emit(this.resolved);

    // Enrich with address via service
    this.geocodeSub?.unsubscribe();
    this.addressLoading = true;

    this.geocodeSub = this.locationService
      .resolveLocationWithAddress(loc)
      .subscribe({
        next: (enriched) => {
          this.resolved = enriched;
          this.addressLoading = false;
          this.locationState.set(enriched);
          this.locationSelected.emit(this.resolved);
        },
        error: () => {
          // Address resolution failed — keep the original label
          this.addressLoading = false;
        }
      });
  }
}

/** Model for a city returned by GET /api/v1/locations/cities */
export interface CityLocation {
  id: number;
  name: string;
  lat: number;
  lng: number;
}

/** Structured result from reverse-geocoding a lat/lng pair. */
export interface GeocodedAddress {
  /** Formatted display string, e.g. "Kondapur, Hyderabad (500083)" */
  formattedAddress: string;
  /** Suburb / neighbourhood, e.g. "Kondapur" */
  area: string;
  /** Road / street / locality */
  street: string;
  /** Postal code, e.g. "500083" */
  pincode: string;
  /** City / town */
  city: string;
}

/** A nearby area suggestion returned by getNearbyAreas(). */
export interface NearbyArea {
  name: string;
  latitude: number;
  longitude: number;
  /** Approximate distance in kilometres from the queried point. */
  distanceKm: number;
}

/** Coordinates resolved by the location picker. */
export interface ResolvedLocation {
  latitude: number;
  longitude: number;
  label: string;        // city name or "Current Location"
  address?: string;     // formatted display address, e.g. "Kondapur, Hyderabad (500083)"
  area?: string;        // suburb / neighbourhood, e.g. "Kondapur"
  street?: string;      // road / street / locality
  pincode?: string;     // postal code
}

