  formattedAddress: string;
  /** Full Google-formatted address */
  fullAddress: string;
  /** Short display, e.g. "Kondapur, Hyderabad" */
  shortAddress: string;
  /** Suburb / neighbourhood, e.g. "Kondapur" */
  area: string;
  /** Road / street / locality */
