/* ── PG Card — vertical premium card ──────────────────────────────── */
.pg-card {
  display: flex;
  flex-direction: column;
  background: var(--color-surface);
  border-radius: var(--radius-xl, 18px);
  overflow: hidden;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.35s var(--ease-out, ease),
              transform 0.35s var(--ease-out, ease);
}

.pg-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-6px);
}

/* ── Image wrapper ────────────────────────────────────────────────── */
.pg-image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--color-border);
}

.pg-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s var(--ease-out, ease);
}

.pg-card:hover .pg-image {
  transform: scale(1.06);
}

.pg-image--empty {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  font-size: 0.85rem;
  background: linear-gradient(135deg, #f3f4f6, #e5e7eb);
}

/* ── Overlay badges ───────────────────────────────────────────────── */
.pg-price-badge {
  position: absolute;
  bottom: 12px;
  right: 12px;
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: #fff;
  font-weight: 700;
  font-size: 1.05rem;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-md, 10px);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.pg-price-badge small {
  font-weight: 400;
  font-size: 0.72rem;
  opacity: 0.85;
}

.pg-distance-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.72rem;
  padding: 0.22rem 0.55rem;
  border-radius: var(--radius-pill, 9999px);
}

/* ── Body ─────────────────────────────────────────────────────────── */
.pg-body {
  padding: 1rem 1.1rem 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  flex: 1;
}

.pg-name {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.pg-location {
  font-size: 0.82rem;
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.pg-location::before {
  content: '';
  font-size: 0.78rem;
}

/* ── Pills (sharing + facility) ───────────────────────────────────── */
.pg-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.pill {
  display: inline-flex;
  align-items: center;
  font-size: 0.72rem;
  padding: 0.22rem 0.55rem;
  border-radius: var(--radius-pill, 9999px);
  font-weight: 500;
  letter-spacing: 0.01em;
  white-space: nowrap;
  transition: background 0.2s ease;
}

.pill--sharing {
  background: var(--color-warning-bg);
  color: var(--color-warning-text);
}

.pill--facility {
  background: #f3f4f6;
  color: var(--color-text-secondary);
}

.pill--more {
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-weight: 600;
}

/* ── View Details button ──────────────────────────────────────────── */
.btn-view {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  width: fit-content;
  border: none;
  background: var(--color-primary);
  color: var(--color-primary-text);
  border-radius: var(--radius-md, 10px);
  padding: 0.5rem 1rem;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s ease, gap 0.25s var(--ease-out, ease);
}

.btn-view:hover {
  background: var(--color-primary-hover);
  gap: 0.65rem;
}

.btn-arrow {
  display: inline-block;
  transition: transform 0.25s var(--ease-out, ease);
}

.btn-view:hover .btn-arrow {
  transform: translateX(3px);
}

/* ── Responsive ───────────────────────────────────────────────────── */
@media (max-width: 600px) {
  .pg-body {
    padding: 0.85rem 1rem 1rem;
  }

  .pg-price-badge {
    font-size: 0.95rem;
    padding: 0.3rem 0.65rem;
  }
}

