import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { PgService } from '../../../../services/pg.service';
import { AuthService } from '../../../../services/auth.service';
import { ResolvedLocation } from '../../../../models/location.model';

const DAYS_OF_WEEK = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'];

const SHORT_DAYS: Record<string, string> = {
  MONDAY: 'Mon', TUESDAY: 'Tue', WEDNESDAY: 'Wed',
  THURSDAY: 'Thu', FRIDAY: 'Fri', SATURDAY: 'Sat', SUNDAY: 'Sun'
};

const FACILITY_OPTIONS = [
  'WiFi', 'AC', 'Laundry', 'Parking', 'Gym',
  'Power Backup', 'Meals', 'TV', 'Geyser', 'Fridge',
  'Water Purifier', 'CCTV', 'Housekeeping', 'Lift'
];

@Component({
  selector: 'app-pg-form-page',
  templateUrl: './pg-form-page.component.html',
  styleUrls: ['./pg-form-page.component.css']
})
export class PgFormPageComponent implements OnInit {

  form!: FormGroup;
  editMode = false;
  pgId: string | null = null;
  loading = false;
  submitting = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;

  /** Step-based navigation: 0 = Basic, 1 = Details, 2 = Media */
  currentStep = 0;
  readonly stepLabels = ['Basic Info', 'Details', 'Media & Submit'];

  readonly daysOfWeek = DAYS_OF_WEEK;
  readonly shortDays = SHORT_DAYS;
  readonly facilityOptions = FACILITY_OPTIONS;
  readonly foodTypes = [
    { label: 'Pure Veg',       value: 'VEG' },
    { label: 'Non-Veg',        value: 'NON_VEG' },
    { label: 'Veg & Non-Veg',  value: 'BOTH' }
  ];

  readonly priceTypes = [
    { label: 'Exact Price',  value: 'EXACT' },
    { label: 'Price Range',  value: 'RANGE' },
    { label: 'Hidden',       value: 'HIDDEN' }
  ];

  constructor(
    private readonly fb: FormBuilder,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly pgService: PgService,
    private readonly authService: AuthService
  ) {}

  ngOnInit(): void {
    this.pgId = this.route.snapshot.paramMap.get('id');
    this.editMode = !!this.pgId;
    this.initForm();

    if (this.editMode && this.pgId) {
      this.loadPg(this.pgId);
    } else {
      this.prefillOwnerFromAuth();
    }
  }

  // ── Form setup ──────────────────────────────────────────────────────

  private initForm(): void {
    this.form = this.fb.group({
      // Owner
      ownerFullName:  ['', [Validators.required, Validators.maxLength(100)]],
      ownerEmail:     ['', [Validators.required, Validators.email, Validators.maxLength(120)]],
      ownerPhone:     ['', [Validators.maxLength(20)]],
      // PG basic
      name:           ['', [Validators.required, Validators.maxLength(150)]],
      description:    ['', [Validators.maxLength(600)]],
      city:           ['', [Validators.maxLength(100)]],
      latitude:       [null, [Validators.required, Validators.min(-90), Validators.max(90)]],
      longitude:      [null, [Validators.required, Validators.min(-180), Validators.max(180)]],
      locationLabel:  ['', [Validators.required, Validators.maxLength(150)]],
      // Sharing options
      sharingOptions: this.fb.array([], Validators.required),
      // Facilities
      selectedFacilities: [[] as string[]],
      // Food
      foodType:       [null],
      nonVegDays:     [[] as string[]],
      eggDays:        [[] as string[]],
      // Pricing
      priceType:      ['EXACT'],
      minPrice:       [null],
      maxPrice:       [null],
      // Images (array of URL strings)
      imageUrls:      this.fb.array([]),
      // Contact details
      contactPhone:   ['', [Validators.maxLength(20)]],
      contactEmail:   ['', [Validators.email, Validators.maxLength(120)]],
      // Weekly menu
      weeklyMenu:     this.fb.group(
        DAYS_OF_WEEK.reduce((acc, day) => {
          acc[day] = [''];
          return acc;
        }, {} as Record<string, any>)
      )
    });
  }

  private prefillOwnerFromAuth(): void {

    const user = this.authService.getCurrentUser();
    console.log(user);
    if (user) {
      this.form.patchValue({
        ownerEmail: user.email,
        contactEmail: user.email
      });
    }
  }

  get sharingOptions(): FormArray {
    return this.form.get('sharingOptions') as FormArray;
  }

  get weeklyMenuGroup(): FormGroup {
    return this.form.get('weeklyMenu') as FormGroup;
  }

  get imageUrls(): FormArray {
    return this.form.get('imageUrls') as FormArray;
  }

  get showNonVegDays(): boolean {
    const ft = this.form.get('foodType')?.value;
    return ft === 'NON_VEG' || ft === 'BOTH';
  }

  get showRangeFields(): boolean {
    return this.form.get('priceType')?.value === 'RANGE';
  }

  addSharingOption(): void {
    this.sharingOptions.push(this.fb.group({
      sharingType: ['SINGLE', Validators.required],
      rent: [null, [Validators.required, Validators.min(1)]],
      availabilityCount: [1, [Validators.required, Validators.min(0)]]
    }));
  }

  removeSharingOption(i: number): void {
    this.sharingOptions.removeAt(i);
  }

  addImageUrl(): void {
    this.imageUrls.push(this.fb.control('', [Validators.required]));
  }

  removeImageUrl(i: number): void {
    this.imageUrls.removeAt(i);
  }

  // ── Location picker integration ────────────────────────────────────

  onLocationPicked(location: ResolvedLocation | null): void {
    if (location) {
      this.form.patchValue({
        latitude: location.latitude,
        longitude: location.longitude,
        locationLabel: location.address || location.label || '',
        city: location.area || ''
      });
    } else {
      this.form.patchValue({
        latitude: null,
        longitude: null,
        locationLabel: '',
        city: ''
      });
    }
  }

  // ── Day toggle helpers ──────────────────────────────────────────────

  toggleDay(controlName: string, day: string): void {
    const current: string[] = this.form.get(controlName)?.value ?? [];
    const idx = current.indexOf(day);
    if (idx >= 0) {
      current.splice(idx, 1);
    } else {
      current.push(day);
    }
    this.form.get(controlName)?.setValue([...current]);
  }

  isDaySelected(controlName: string, day: string): boolean {
    const current: string[] = this.form.get(controlName)?.value ?? [];
    return current.includes(day);
  }

  toggleFacility(name: string): void {
    const current: string[] = this.form.get('selectedFacilities')?.value ?? [];
    const idx = current.indexOf(name);
    if (idx >= 0) {
      current.splice(idx, 1);
    } else {
      current.push(name);
    }
    this.form.get('selectedFacilities')?.setValue([...current]);
  }

  isFacilitySelected(name: string): boolean {
    const current: string[] = this.form.get('selectedFacilities')?.value ?? [];
    return current.includes(name);
  }

  // ── Step navigation ─────────────────────────────────────────────────

  nextStep(): void {
    if (this.currentStep === 0 && !this.isStep0Valid()) {
      this.markStep0Touched();
      return;
    }
    if (this.currentStep < this.stepLabels.length - 1) {
      this.currentStep++;
    }
  }

  prevStep(): void {
    if (this.currentStep > 0) {
      this.currentStep--;
    }
  }

  goToStep(step: number): void {
    if (step < this.currentStep) {
      this.currentStep = step;
    } else if (step === this.currentStep + 1) {
      this.nextStep();
    }
  }

  private isStep0Valid(): boolean {
    const fields = ['name', 'latitude', 'longitude', 'locationLabel'];
    if (!this.editMode) {
      fields.push('ownerFullName', 'ownerEmail');
    }
    return fields.every(f => this.form.get(f)?.valid);
  }

  private markStep0Touched(): void {
    const fields = ['name', 'latitude', 'longitude', 'locationLabel', 'ownerFullName', 'ownerEmail', 'ownerPhone'];
    fields.forEach(f => this.form.get(f)?.markAsTouched());
  }

  // ── Helper for inline validation ────────────────────────────────────

  hasError(controlName: string, error: string): boolean {
    const ctrl = this.form.get(controlName);
    return !!ctrl && ctrl.hasError(error) && ctrl.touched;
  }

  // ── Load existing PG (edit mode) ────────────────────────────────────

  private loadPg(id: string): void {
    this.loading = true;
    this.pgService.getPgById(id).subscribe({
      next: (pg) => {
        this.form.patchValue({
          ownerFullName: pg.owner?.fullName,
          ownerEmail: pg.owner?.email,
          ownerPhone: pg.owner?.phoneNumber,
          name: pg.name,
          description: pg.description,
          latitude: pg.latitude,
          longitude: pg.longitude,
          locationLabel: pg.locationLabel,
          foodType: pg.foodType ?? null,
          nonVegDays: pg.nonVegDays ?? [],
          eggDays: pg.eggDays ?? [],
          selectedFacilities: pg.facilities ?? [],
          priceType: pg.priceType ?? 'EXACT',
          minPrice: pg.minPrice ?? null,
          maxPrice: pg.maxPrice ?? null
        });

        // Sharing options
        this.sharingOptions.clear();
        (pg.sharingOptions ?? []).forEach(opt => {
          this.sharingOptions.push(this.fb.group({
            sharingType: [opt.sharingType, Validators.required],
            rent: [opt.rent, [Validators.required, Validators.min(1)]],
            availabilityCount: [opt.availabilityCount, [Validators.required, Validators.min(0)]]
          }));
        });

        // Images
        this.imageUrls.clear();
        (pg.images ?? []).forEach(img => {
          this.imageUrls.push(this.fb.control(img.imageUrl, [Validators.required]));
        });

        // Weekly menu
        if (pg.weeklyMenu) {
          for (const day of DAYS_OF_WEEK) {
            const items = pg.weeklyMenu[day] ?? [];
            this.weeklyMenuGroup.get(day)?.setValue(items.join(', '));
          }
        }

        this.loading = false;
      },
      error: (err) => {
        this.errorMessage = err.error?.message ?? 'Failed to load PG for editing.';
        this.loading = false;
      }
    });
  }

  // ── Submit ──────────────────────────────────────────────────────────

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.submitting = true;
    this.errorMessage = null;
    this.successMessage = null;

    const val = this.form.value;

    // Build weeklyMenu map from comma-separated strings
    const weeklyMenu: Record<string, string[]> = {};
    let hasMenu = false;
    for (const day of DAYS_OF_WEEK) {
      const raw = (val.weeklyMenu?.[day] ?? '').trim();
      if (raw) {
        weeklyMenu[day] = raw.split(',').map((s: string) => s.trim()).filter((s: string) => s);
        hasMenu = true;
      }
    }

    // Build images array from URL strings
    const images = (val.imageUrls ?? [])
      .filter((url: string) => url?.trim())
      .map((url: string, idx: number) => ({ imageUrl: url.trim(), displayOrder: idx + 1 }));

    const body: Record<string, unknown> = {
      owner: {
        fullName: val.ownerFullName,
        email: val.ownerEmail,
        phoneNumber: val.ownerPhone || null
      },
      name: val.name,
      description: val.description || null,
      latitude: val.latitude,
      longitude: val.longitude,
      locationLabel: val.locationLabel,
      sharingOptions: val.sharingOptions,
      facilityNames: val.selectedFacilities?.length > 0 ? val.selectedFacilities : null,
      foodType: val.foodType || null,
      weeklyMenu: hasMenu ? weeklyMenu : null,
      nonVegDays: val.nonVegDays?.length > 0 ? val.nonVegDays : null,
      eggDays: val.eggDays?.length > 0 ? val.eggDays : null,
      priceType: val.priceType || 'EXACT',
      minPrice: val.priceType === 'RANGE' ? val.minPrice : null,
      maxPrice: val.priceType === 'RANGE' ? val.maxPrice : null,
      images: images.length > 0 ? images : null
    };

    const req$ = this.editMode
      ? this.pgService.updatePg(this.pgId!, body)
      : this.pgService.createPg(body);

    req$.subscribe({
      next: () => {
        this.submitting = false;
        this.successMessage = this.editMode
          ? 'PG updated successfully! Redirecting…'
          : 'PG created successfully! Redirecting to listings…';
        // Redirect to PG search (listings) after short delay
        setTimeout(() => this.router.navigate(['/pg-search']), 1500);
      },
      error: (err) => {
        this.submitting = false;
        this.errorMessage = err.error?.message ?? 'Failed to save PG. Please try again.';
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/pg-search']);
  }
}

import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { PgService } from '../../../../services/pg.service';
import { AuthService } from '../../../../services/auth.service';
import { ResolvedLocation } from '../../../../models/location.model';

const DAYS_OF_WEEK = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'];

const SHORT_DAYS: Record<string, string> = {
  MONDAY: 'Mon', TUESDAY: 'Tue', WEDNESDAY: 'Wed',
  THURSDAY: 'Thu', FRIDAY: 'Fri', SATURDAY: 'Sat', SUNDAY: 'Sun'
};

const FACILITY_OPTIONS = [
  'WiFi', 'AC', 'Laundry', 'Parking', 'Gym',
  'Power Backup', 'Meals', 'TV', 'Geyser', 'Fridge',
  'Water Purifier', 'CCTV', 'Housekeeping', 'Lift'
];

@Component({
  selector: 'app-pg-form-page',
  templateUrl: './pg-form-page.component.html',
  styleUrls: ['./pg-form-page.component.css']
})
export class PgFormPageComponent implements OnInit {

  form!: FormGroup;
  editMode = false;
  pgId: string | null = null;
  loading = false;
  submitting = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;

  /** Step-based navigation: 0 = Basic, 1 = Details, 2 = Media */
  currentStep = 0;
  readonly stepLabels = ['Basic Info', 'Details', 'Media & Submit'];

  readonly daysOfWeek = DAYS_OF_WEEK;
  readonly shortDays = SHORT_DAYS;
  readonly facilityOptions = FACILITY_OPTIONS;
  readonly foodTypes = [
    { label: 'Pure Veg',       value: 'VEG' },
    { label: 'Non-Veg',        value: 'NON_VEG' },
    { label: 'Veg & Non-Veg',  value: 'BOTH' }
  ];

  readonly priceTypes = [
    { label: 'Exact Price',  value: 'EXACT' },
    { label: 'Price Range',  value: 'RANGE' },
    { label: 'Hidden',       value: 'HIDDEN' }
  ];

  constructor(
    private readonly fb: FormBuilder,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly pgService: PgService,
    private readonly authService: AuthService
  ) {}

  ngOnInit(): void {
    this.pgId = this.route.snapshot.paramMap.get('id');
    this.editMode = !!this.pgId;
    this.initForm();

    if (this.editMode && this.pgId) {
      this.loadPg(this.pgId);
    } else {
      this.prefillOwnerFromAuth();
    }
  }

  // ── Form setup ──────────────────────────────────────────────────────

  private initForm(): void {
    this.form = this.fb.group({
      // Owner
      ownerFullName:  ['', [Validators.required, Validators.maxLength(100)]],
      ownerEmail:     ['', [Validators.required, Validators.email, Validators.maxLength(120)]],
      ownerPhone:     ['', [Validators.maxLength(20)]],
      // PG basic
      name:           ['', [Validators.required, Validators.maxLength(150)]],
      description:    ['', [Validators.maxLength(600)]],
      city:           ['', [Validators.maxLength(100)]],
      latitude:       [null, [Validators.required, Validators.min(-90), Validators.max(90)]],
      longitude:      [null, [Validators.required, Validators.min(-180), Validators.max(180)]],
      locationLabel:  ['', [Validators.required, Validators.maxLength(150)]],
      // Sharing options
      sharingOptions: this.fb.array([], Validators.required),
      // Facilities
      selectedFacilities: [[] as string[]],
      // Food
      foodType:       [null],
      nonVegDays:     [[] as string[]],
      eggDays:        [[] as string[]],
      // Pricing
      priceType:      ['EXACT'],
      minPrice:       [null],
      maxPrice:       [null],
      // Images (array of URL strings)
      imageUrls:      this.fb.array([]),
      // Contact details
      contactPhone:   ['', [Validators.maxLength(20)]],
      contactEmail:   ['', [Validators.email, Validators.maxLength(120)]],
      // Weekly menu
      weeklyMenu:     this.fb.group(
        DAYS_OF_WEEK.reduce((acc, day) => {
          acc[day] = [''];
          return acc;
        }, {} as Record<string, any>)
      )
    });
  }

  private prefillOwnerFromAuth(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      this.form.patchValue({
        ownerFullName: user.fullName || '',
        ownerEmail: user.email,
        ownerPhone: user.phoneNumber || '',
        contactEmail: user.email,
        contactPhone: user.phoneNumber || ''
      });
    }
  }

  get sharingOptions(): FormArray {
    return this.form.get('sharingOptions') as FormArray;
  }

  get weeklyMenuGroup(): FormGroup {
    return this.form.get('weeklyMenu') as FormGroup;
  }

  get imageUrls(): FormArray {
    return this.form.get('imageUrls') as FormArray;
  }

  get showNonVegDays(): boolean {
    const ft = this.form.get('foodType')?.value;
    return ft === 'NON_VEG' || ft === 'BOTH';
  }

  get showRangeFields(): boolean {
    return this.form.get('priceType')?.value === 'RANGE';
  }

  addSharingOption(): void {
    this.sharingOptions.push(this.fb.group({
      sharingType: ['SINGLE', Validators.required],
      rent: [null, [Validators.required, Validators.min(1)]],
      availabilityCount: [1, [Validators.required, Validators.min(0)]]
    }));
  }

  removeSharingOption(i: number): void {
    this.sharingOptions.removeAt(i);
  }

  addImageUrl(): void {
    this.imageUrls.push(this.fb.control('', [Validators.required]));
  }

  removeImageUrl(i: number): void {
    this.imageUrls.removeAt(i);
  }

  // ── Location picker integration ────────────────────────────────────

  onLocationPicked(location: ResolvedLocation | null): void {
    if (location) {
      this.form.patchValue({
        latitude: location.latitude,
        longitude: location.longitude,
        locationLabel: location.address || location.label || '',
        city: location.area || ''
      });
    } else {
      this.form.patchValue({
        latitude: null,
        longitude: null,
        locationLabel: '',
        city: ''
      });
    }
  }

  // ── Day toggle helpers ──────────────────────────────────────────────

  toggleDay(controlName: string, day: string): void {
    const current: string[] = this.form.get(controlName)?.value ?? [];
    const idx = current.indexOf(day);
    if (idx >= 0) {
      current.splice(idx, 1);
    } else {
      current.push(day);
    }
    this.form.get(controlName)?.setValue([...current]);
  }

  isDaySelected(controlName: string, day: string): boolean {
    const current: string[] = this.form.get(controlName)?.value ?? [];
    return current.includes(day);
  }

  toggleFacility(name: string): void {
    const current: string[] = this.form.get('selectedFacilities')?.value ?? [];
    const idx = current.indexOf(name);
    if (idx >= 0) {
      current.splice(idx, 1);
    } else {
      current.push(name);
    }
    this.form.get('selectedFacilities')?.setValue([...current]);
  }

  isFacilitySelected(name: string): boolean {
    const current: string[] = this.form.get('selectedFacilities')?.value ?? [];
    return current.includes(name);
  }

  // ── Step navigation ─────────────────────────────────────────────────

  nextStep(): void {
    if (this.currentStep === 0 && !this.isStep0Valid()) {
      this.markStep0Touched();
      return;
    }
    if (this.currentStep < this.stepLabels.length - 1) {
      this.currentStep++;
    }
  }

  prevStep(): void {
    if (this.currentStep > 0) {
      this.currentStep--;
    }
  }

  goToStep(step: number): void {
    if (step < this.currentStep) {
      this.currentStep = step;
    } else if (step === this.currentStep + 1) {
      this.nextStep();
    }
  }

  private isStep0Valid(): boolean {
    const fields = ['name', 'latitude', 'longitude', 'locationLabel'];
    if (!this.editMode) {
      fields.push('ownerFullName', 'ownerEmail');
    }
    return fields.every(f => this.form.get(f)?.valid);
  }

  private markStep0Touched(): void {
    const fields = ['name', 'latitude', 'longitude', 'locationLabel', 'ownerFullName', 'ownerEmail', 'ownerPhone'];
    fields.forEach(f => this.form.get(f)?.markAsTouched());
  }

  // ── Helper for inline validation ────────────────────────────────────

  hasError(controlName: string, error: string): boolean {
    const ctrl = this.form.get(controlName);
    return !!ctrl && ctrl.hasError(error) && ctrl.touched;
  }

  // ── Load existing PG (edit mode) ────────────────────────────────────

  private loadPg(id: string): void {
    this.loading = true;
    this.pgService.getPgById(id).subscribe({
      next: (pg) => {
        this.form.patchValue({
          ownerFullName: pg.owner?.fullName,
          ownerEmail: pg.owner?.email,
          ownerPhone: pg.owner?.phoneNumber,
          name: pg.name,
          description: pg.description,
          latitude: pg.latitude,
          longitude: pg.longitude,
          locationLabel: pg.locationLabel,
          foodType: pg.foodType ?? null,
          nonVegDays: pg.nonVegDays ?? [],
          eggDays: pg.eggDays ?? [],
          selectedFacilities: pg.facilities ?? [],
          priceType: pg.priceType ?? 'EXACT',
          minPrice: pg.minPrice ?? null,
          maxPrice: pg.maxPrice ?? null
        });

        // Sharing options
        this.sharingOptions.clear();
        (pg.sharingOptions ?? []).forEach(opt => {
          this.sharingOptions.push(this.fb.group({
            sharingType: [opt.sharingType, Validators.required],
            rent: [opt.rent, [Validators.required, Validators.min(1)]],
            availabilityCount: [opt.availabilityCount, [Validators.required, Validators.min(0)]]
          }));
        });

        // Images
        this.imageUrls.clear();
        (pg.images ?? []).forEach(img => {
          this.imageUrls.push(this.fb.control(img.imageUrl, [Validators.required]));
        });

        // Weekly menu
        if (pg.weeklyMenu) {
          for (const day of DAYS_OF_WEEK) {
            const items = pg.weeklyMenu[day] ?? [];
            this.weeklyMenuGroup.get(day)?.setValue(items.join(', '));
          }
        }

        this.loading = false;
      },
      error: (err) => {
        this.errorMessage = err.error?.message ?? 'Failed to load PG for editing.';
        this.loading = false;
      }
    });
  }

  // ── Submit ──────────────────────────────────────────────────────────

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.submitting = true;
    this.errorMessage = null;
    this.successMessage = null;

    const val = this.form.value;

    // Build weeklyMenu map from comma-separated strings
    const weeklyMenu: Record<string, string[]> = {};
    let hasMenu = false;
    for (const day of DAYS_OF_WEEK) {
      const raw = (val.weeklyMenu?.[day] ?? '').trim();
      if (raw) {
        weeklyMenu[day] = raw.split(',').map((s: string) => s.trim()).filter((s: string) => s);
        hasMenu = true;
      }
    }

    // Build images array from URL strings
    const images = (val.imageUrls ?? [])
      .filter((url: string) => url?.trim())
      .map((url: string, idx: number) => ({ imageUrl: url.trim(), displayOrder: idx + 1 }));

    const body: Record<string, unknown> = {
      owner: {
        fullName: val.ownerFullName,
        email: val.ownerEmail,
        phoneNumber: val.ownerPhone || null
      },
      name: val.name,
      description: val.description || null,
      latitude: val.latitude,
      longitude: val.longitude,
      locationLabel: val.locationLabel,
      sharingOptions: val.sharingOptions,
      facilityNames: val.selectedFacilities?.length > 0 ? val.selectedFacilities : null,
      foodType: val.foodType || null,
      weeklyMenu: hasMenu ? weeklyMenu : null,
      nonVegDays: val.nonVegDays?.length > 0 ? val.nonVegDays : null,
      eggDays: val.eggDays?.length > 0 ? val.eggDays : null,
      priceType: val.priceType || 'EXACT',
      minPrice: val.priceType === 'RANGE' ? val.minPrice : null,
      maxPrice: val.priceType === 'RANGE' ? val.maxPrice : null,
      images: images.length > 0 ? images : null
    };

    const req$ = this.editMode
      ? this.pgService.updatePg(this.pgId!, body)
      : this.pgService.createPg(body);

    req$.subscribe({
      next: () => {
        this.submitting = false;
        this.successMessage = this.editMode
          ? 'PG updated successfully! Redirecting…'
          : 'PG created successfully! Redirecting to listings…';
        // Redirect to PG search (listings) after short delay
        setTimeout(() => this.router.navigate(['/pg-search']), 1500);
      },
      error: (err) => {
        this.submitting = false;
        this.errorMessage = err.error?.message ?? 'Failed to save PG. Please try again.';
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/pg-search']);
  }
}

import { Component, HostListener, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { PgListing, PgSearchFilters } from '../../../../models/pg.model';
import { PgService } from '../../../../services/pg.service';
import { FilterField } from '../../../../components/filters-panel/filters-panel.component';

/** Well-known facility names shown as checkboxes. */
const FACILITY_OPTIONS = [
  'WiFi', 'AC', 'Laundry', 'Parking', 'Gym',
  'Power Backup', 'Meals', 'TV', 'Geyser', 'Fridge'
];

const SHARING_TYPES = ['SINGLE', 'DOUBLE', 'TRIPLE', 'FOUR_SHARING'];

const PAGE_SIZE = 20;

@Component({
  selector: 'app-pg-search-page',
  templateUrl: './pg-search-page.component.html',
  styleUrls: ['./pg-search-page.component.css']
})
export class PgSearchPageComponent implements OnInit, OnDestroy {

  // ── Template-bound state ────────────────────────────────────────────
  pgs: PgListing[] = [];
  loading = false;
  errorMessage: string | null = null;
  isLastPage = false;
  totalElements = 0;
  totalPages = 0;

  /** Filter panel configuration. */
  filterFields: FilterField[] = [
    { key: 'latitude',      label: 'Latitude',      type: 'number', placeholder: 'e.g. 12.9716' },
    { key: 'longitude',     label: 'Longitude',     type: 'number', placeholder: 'e.g. 77.5946' },
    { key: 'radiusKm',     label: 'Radius (km)',    type: 'number', placeholder: 'e.g. 5' },
    { key: 'minPrice',     label: 'Min Price (₹)',  type: 'number', placeholder: '0' },
    { key: 'maxPrice',     label: 'Max Price (₹)',  type: 'number', placeholder: '20000' },
    { key: 'sharingType',  label: 'Sharing Type',   type: 'select', options: SHARING_TYPES },
    { key: 'facilityNames', label: 'Facilities',    type: 'checkbox-group', options: FACILITY_OPTIONS }
  ];

  // ── Private state ───────────────────────────────────────────────────
  private currentPage = 0;
  private activeFilters: PgSearchFilters = {};

  /** Guards against duplicate / overlapping API calls. */
  private searchSub: Subscription | null = null;

  constructor(private readonly pgService: PgService) {}

  // ── Lifecycle ───────────────────────────────────────────────────────

  ngOnInit(): void {
    this.loadInitial();
  }

  ngOnDestroy(): void {
    this.searchSub?.unsubscribe();
  }

  // ── Public API (used by template) ───────────────────────────────────

  /**
   * Loads the first page of results with the currently active filters.
   * Resets all pagination state and clears existing results.
   */
  loadInitial(): void {
    this.currentPage = 0;
    this.pgs = [];
    this.isLastPage = false;
    this.totalElements = 0;
    this.totalPages = 0;
    this.fetchPage(0);
  }

  /**
   * Appends the next page of results (infinite scroll).
   * No-ops if already loading or on the last page.
   */
  loadMore(): void {
    if (this.loading || this.isLastPage) {
      return;
    }
    this.fetchPage(this.currentPage + 1);
  }

  /**
   * Called by the filters panel.
   * Parses raw form values, stores them as active filters,
   * and triggers a fresh first-page load.
   */
  resetSearch(raw: Record<string, unknown>): void {
    this.activeFilters = this.parseFilters(raw);
    this.loadInitial();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // ── Infinite Scroll ─────────────────────────────────────────────────

  @HostListener('window:scroll')
  onScroll(): void {
    if (this.loading || this.isLastPage) {
      return;
    }

    const scrollY = window.scrollY || document.documentElement.scrollTop;
    const viewportHeight = window.innerHeight;
    const docHeight = document.documentElement.scrollHeight;

    // Trigger when within 300px of the bottom
    if (scrollY + viewportHeight >= docHeight - 300) {
      this.loadMore();
    }
  }

  // ── Private ─────────────────────────────────────────────────────────

  /**
   * Core fetch method. Cancels any in-flight request before starting
   * a new one to prevent duplicate / stale responses.
   */
  private fetchPage(page: number): void {
    // Cancel previous in-flight request (prevents race conditions)
    this.searchSub?.unsubscribe();

    this.loading = true;
    this.errorMessage = null;
    this.currentPage = page;

    this.searchSub = this.pgService
      .searchPgs(this.activeFilters, page, PAGE_SIZE)
      .subscribe({
        next: (res) => {
          // Page 0 → replace; subsequent pages → append
          this.pgs = page === 0 ? res.content : [...this.pgs, ...res.content];
          this.isLastPage = res.last;
          this.totalElements = res.totalElements;
          this.totalPages = res.totalPages;
          this.loading = false;
        },
        error: (err) => {
          this.errorMessage =
            err.error?.message ?? 'Failed to load PG listings. Please try again.';
          this.loading = false;
        }
      });
  }

  /** Converts raw filter-panel form values to typed PgSearchFilters. */
  private parseFilters(raw: Record<string, unknown>): PgSearchFilters {
    const num = (v: unknown): number | undefined => {
      if (v === null || v === undefined || v === '') return undefined;
      const n = Number(v);
      return isNaN(n) ? undefined : n;
    };

    const str = (v: unknown): string | undefined => {
      if (v === null || v === undefined || v === '') return undefined;
      return String(v);
    };

    return {
      latitude:      num(raw['latitude']),
      longitude:     num(raw['longitude']),
      radiusKm:     num(raw['radiusKm']),
      minPrice:     num(raw['minPrice']),
      maxPrice:     num(raw['maxPrice']),
      sharingType:  str(raw['sharingType']),
      facilityNames: Array.isArray(raw['facilityNames']) && raw['facilityNames'].length > 0
        ? raw['facilityNames'] as string[]
        : undefined
    };
  }
}

import { Component, HostListener, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { PgListing, PgSearchFilters } from '../../../../models/pg.model';
import { PgService } from '../../../../services/pg.service';
import { FilterField } from '../../../../components/filters-panel/filters-panel.component';

/** Well-known facility names shown as checkboxes. */
const FACILITY_OPTIONS = [
  'WiFi', 'AC', 'Laundry', 'Parking', 'Gym',
  'Power Backup', 'Meals', 'TV', 'Geyser', 'Fridge'
];

const SHARING_TYPES = ['SINGLE', 'DOUBLE', 'TRIPLE', 'FOUR_SHARING'];

const PAGE_SIZE = 20;

@Component({
  selector: 'app-pg-search-page',
  templateUrl: './pg-search-page.component.html',
  styleUrls: ['./pg-search-page.component.css']
})
export class PgSearchPageComponent implements OnInit, OnDestroy {

  // ── Template-bound state ────────────────────────────────────────────
  pgs: PgListing[] = [];
  loading = false;
  errorMessage: string | null = null;
  isLastPage = false;
  totalElements = 0;
  totalPages = 0;

  /** Filter panel configuration. */
  filterFields: FilterField[] = [
    { key: 'latitude',      label: 'Latitude',      type: 'number', placeholder: 'e.g. 12.9716' },
    { key: 'longitude',     label: 'Longitude',     type: 'number', placeholder: 'e.g. 77.5946' },
    { key: 'radiusKm',     label: 'Radius (km)',    type: 'number', placeholder: 'e.g. 5' },
    { key: 'minPrice',     label: 'Min Price (₹)',  type: 'number', placeholder: '0' },
    { key: 'maxPrice',     label: 'Max Price (₹)',  type: 'number', placeholder: '20000' },
    { key: 'sharingType',  label: 'Sharing Type',   type: 'select', options: SHARING_TYPES },
    { key: 'facilityNames', label: 'Facilities',    type: 'checkbox-group', options: FACILITY_OPTIONS }
  ];

  // ── Private state ───────────────────────────────────────────────────
  private currentPage = 0;
  private activeFilters: PgSearchFilters = {};

  /** Guards against duplicate / overlapping API calls. */
  private searchSub: Subscription | null = null;

  constructor(private readonly pgService: PgService) {}

  // ── Lifecycle ───────────────────────────────────────────────────────

  ngOnInit(): void {
    this.loadInitial();
  }

  ngOnDestroy(): void {
    this.searchSub?.unsubscribe();
  }

  // ── Public API (used by template) ───────────────────────────────────

  /**
   * Loads the first page of results with the currently active filters.
   * Resets all pagination state and clears existing results.
   */
  loadInitial(): void {
    this.currentPage = 0;
    this.pgs = [];
    this.isLastPage = false;
    this.totalElements = 0;
    this.totalPages = 0;
    this.fetchPage(0);
  }

  /**
   * Appends the next page of results (infinite scroll).
   * No-ops if already loading or on the last page.
   */
  loadMore(): void {
    if (this.loading || this.isLastPage) {
      return;
    }
    this.fetchPage(this.currentPage + 1);
  }

  /**
   * Called by the filters panel.
   * Parses raw form values, stores them as active filters,
   * and triggers a fresh first-page load.
   */
  resetSearch(raw: Record<string, unknown>): void {
    this.activeFilters = this.parseFilters(raw);
    this.loadInitial();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  /** trackBy for ngFor — prevents re-rendering cards that haven't changed. */
  trackByPgId(_index: number, pg: PgListing): number {
    return pg.id;
  }

  // ── Infinite Scroll ─────────────────────────────────────────────────

  @HostListener('window:scroll')
  onScroll(): void {
    if (this.loading || this.isLastPage) {
      return;
    }

    const scrollY = window.scrollY || document.documentElement.scrollTop;
    const viewportHeight = window.innerHeight;
    const docHeight = document.documentElement.scrollHeight;

    // Trigger when within 300px of the bottom
    if (scrollY + viewportHeight >= docHeight - 300) {
      this.loadMore();
    }
  }

  // ── Private ─────────────────────────────────────────────────────────

  /**
   * Core fetch method. Cancels any in-flight request before starting
   * a new one to prevent duplicate / stale responses.
   */
  private fetchPage(page: number): void {
    // Cancel previous in-flight request (prevents race conditions)
    this.searchSub?.unsubscribe();

    this.loading = true;
    this.errorMessage = null;
    this.currentPage = page;

    this.searchSub = this.pgService
      .searchPgs(this.activeFilters, page, PAGE_SIZE)
      .subscribe({
        next: (res) => {
          // Page 0 → replace; subsequent pages → append
          this.pgs = page === 0 ? res.content : [...this.pgs, ...res.content];
          this.isLastPage = res.last;
          this.totalElements = res.totalElements;
          this.totalPages = res.totalPages;
          this.loading = false;
        },
        error: (err) => {
          this.errorMessage =
            err.error?.message ?? 'Failed to load PG listings. Please try again.';
          this.loading = false;
        }
      });
  }

  /** Converts raw filter-panel form values to typed PgSearchFilters. */
  private parseFilters(raw: Record<string, unknown>): PgSearchFilters {
    const num = (v: unknown): number | undefined => {
      if (v === null || v === undefined || v === '') return undefined;
      const n = Number(v);
      return isNaN(n) ? undefined : n;
    };

    const str = (v: unknown): string | undefined => {
      if (v === null || v === undefined || v === '') return undefined;
      return String(v);
    };

    return {
      latitude:      num(raw['latitude']),
      longitude:     num(raw['longitude']),
      radiusKm:     num(raw['radiusKm']),
      minPrice:     num(raw['minPrice']),
      maxPrice:     num(raw['maxPrice']),
      sharingType:  str(raw['sharingType']),
      facilityNames: Array.isArray(raw['facilityNames']) && raw['facilityNames'].length > 0
        ? raw['facilityNames'] as string[]
        : undefined
    };
  }
}

BEGIN;

CREATE TABLE IF NOT EXISTS app_users (
    id BIGSERIAL PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(120) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    phone_number VARCHAR(20),
    role VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(120) NOT NULL UNIQUE,
    phone_number VARCHAR(20),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS owner_profiles (
    id BIGSERIAL PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(120) NOT NULL UNIQUE,
    phone_number VARCHAR(20),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pg (
    id BIGSERIAL PRIMARY KEY,
    owner_id BIGINT NOT NULL REFERENCES owner_profiles(id),
    name VARCHAR(150) NOT NULL,
    description VARCHAR(600),
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    location_label VARCHAR(150) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sharing_options (
    id BIGSERIAL PRIMARY KEY,
    pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE,
    sharing_type VARCHAR(40) NOT NULL,
    rent NUMERIC(10,2) NOT NULL CHECK (rent > 0),
    availability_count INTEGER NOT NULL CHECK (availability_count >= 0),
    UNIQUE(pg_id, sharing_type)
);

CREATE TABLE IF NOT EXISTS facilities (
    id BIGSERIAL PRIMARY KEY,
    facility_name VARCHAR(80) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS pg_facilities (
    id BIGSERIAL PRIMARY KEY,
    pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE,
    facility_id BIGINT NOT NULL REFERENCES facilities(id),
    UNIQUE (pg_id, facility_id)
);

CREATE TABLE IF NOT EXISTS images (
    id BIGSERIAL PRIMARY KEY,
    pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE,
    image_url TEXT NOT NULL,
    display_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS preferences (
    id BIGSERIAL PRIMARY KEY,
    food_preference VARCHAR(50),
    smoking_preference VARCHAR(50),
    preferred_gender VARCHAR(50),
    additional_notes VARCHAR(300)
);

CREATE TABLE IF NOT EXISTS tenant_posts (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id),
    preference_id BIGINT UNIQUE REFERENCES preferences(id) ON DELETE SET NULL,
    title VARCHAR(120) NOT NULL,
    description VARCHAR(500),
    min_budget NUMERIC(10,2) NOT NULL CHECK (min_budget > 0),
    max_budget NUMERIC(10,2) NOT NULL CHECK (max_budget >= min_budget),
    preferred_latitude DOUBLE PRECISION NOT NULL,
    preferred_longitude DOUBLE PRECISION NOT NULL,
    location_label VARCHAR(120) NOT NULL,
    move_in_date DATE NOT NULL,
    total_capacity INTEGER NOT NULL DEFAULT 1 CHECK (total_capacity >= 1),
    current_occupancy INTEGER NOT NULL DEFAULT 0 CHECK (current_occupancy >= 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_occupancy_lte_capacity CHECK (current_occupancy <= total_capacity)
);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id BIGSERIAL PRIMARY KEY,
    token VARCHAR(255) NOT NULL UNIQUE,
    user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    expiry_date TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_pg_geo ON pg (latitude, longitude);
CREATE INDEX IF NOT EXISTS idx_pg_active ON pg (is_active);
CREATE INDEX IF NOT EXISTS idx_sharing_option_filter ON sharing_options (sharing_type, rent);
CREATE INDEX IF NOT EXISTS idx_pg_facilities_facility ON pg_facilities (facility_id);
CREATE INDEX IF NOT EXISTS idx_tenant_post_budget ON tenant_posts (min_budget, max_budget);
CREATE INDEX IF NOT EXISTS idx_tenant_post_geo ON tenant_posts (preferred_latitude, preferred_longitude);
CREATE INDEX IF NOT EXISTS idx_tenant_post_active_movein ON tenant_posts (is_active, move_in_date);
CREATE TABLE IF NOT EXISTS cities (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE,
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_refresh_token ON refresh_tokens (token);
CREATE INDEX IF NOT EXISTS idx_refresh_token_user ON refresh_tokens (user_id);

COMMIT;

BEGIN;
CREATE TABLE IF NOT EXISTS app_users ( id BIGSERIAL PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, phone_number VARCHAR(20), role VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE TABLE IF NOT EXISTS users ( id BIGSERIAL PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, phone_number VARCHAR(20), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE TABLE IF NOT EXISTS owner_profiles ( id BIGSERIAL PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, phone_number VARCHAR(20), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE TABLE IF NOT EXISTS pg ( id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES owner_profiles(id), name VARCHAR(150) NOT NULL, description VARCHAR(600), latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, location_label VARCHAR(150) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, food_type VARCHAR(20), weekly_menu TEXT, non_veg_days TEXT, egg_days TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE TABLE IF NOT EXISTS sharing_options ( id BIGSERIAL PRIMARY KEY, pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE, sharing_type VARCHAR(40) NOT NULL, rent NUMERIC(10,2) NOT NULL CHECK (rent > 0), availability_count INTEGER NOT NULL CHECK (availability_count >= 0), UNIQUE(pg_id, sharing_type) );
CREATE TABLE IF NOT EXISTS facilities ( id BIGSERIAL PRIMARY KEY, facility_name VARCHAR(80) NOT NULL UNIQUE );
CREATE TABLE IF NOT EXISTS pg_facilities ( id BIGSERIAL PRIMARY KEY, pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE, facility_id BIGINT NOT NULL REFERENCES facilities(id), UNIQUE (pg_id, facility_id) );
CREATE TABLE IF NOT EXISTS images ( id BIGSERIAL PRIMARY KEY, pg_id BIGINT NOT NULL REFERENCES pg(id) ON DELETE CASCADE, image_url TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS preferences ( id BIGSERIAL PRIMARY KEY, food_preference VARCHAR(50), smoking_preference VARCHAR(50), preferred_gender VARCHAR(50), additional_notes VARCHAR(300) );
CREATE TABLE IF NOT EXISTS tenant_posts ( id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), preference_id BIGINT UNIQUE REFERENCES preferences(id) ON DELETE SET NULL, title VARCHAR(120) NOT NULL, description VARCHAR(500), min_budget NUMERIC(10,2) NOT NULL CHECK (min_budget > 0), max_budget NUMERIC(10,2) NOT NULL CHECK (max_budget >= min_budget), preferred_latitude DOUBLE PRECISION NOT NULL, preferred_longitude DOUBLE PRECISION NOT NULL, location_label VARCHAR(120) NOT NULL, move_in_date DATE NOT NULL, total_capacity INTEGER NOT NULL DEFAULT 1 CHECK (total_capacity >= 1), current_occupancy INTEGER NOT NULL DEFAULT 0 CHECK (current_occupancy >= 0), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT chk_occupancy_lte_capacity CHECK (current_occupancy <= total_capacity) );
CREATE TABLE IF NOT EXISTS refresh_tokens ( id BIGSERIAL PRIMARY KEY, token VARCHAR(255) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, expiry_date TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX IF NOT EXISTS idx_pg_geo ON pg (latitude, longitude); CREATE INDEX IF NOT EXISTS idx_pg_active ON pg (is_active); CREATE INDEX IF NOT EXISTS idx_sharing_option_filter ON sharing_options (sharing_type, rent); CREATE INDEX IF NOT EXISTS idx_pg_facilities_facility ON pg_facilities (facility_id); CREATE INDEX IF NOT EXISTS idx_tenant_post_budget ON tenant_posts (min_budget, max_budget); CREATE INDEX IF NOT EXISTS idx_tenant_post_geo ON tenant_posts (preferred_latitude, preferred_longitude); CREATE INDEX IF NOT EXISTS idx_tenant_post_active_movein ON tenant_posts (is_active, move_in_date); CREATE TABLE IF NOT EXISTS cities ( id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX IF NOT EXISTS idx_refresh_token ON refresh_tokens (token); CREATE INDEX IF NOT EXISTS idx_refresh_token_user ON refresh_tokens (user_id);
COMMIT;

/* ── Angular Material Theme ─────────────────────────────────────────── */
@import '@angular/material/prebuilt-themes/indigo-pink.css';

/* ── Design Tokens (CSS Custom Properties) ─────────────────────────── */
:root {
  /* Primary — deep blue */
  --color-primary:        #1e3a8a;
  --color-primary-hover:  #172e6e;
  --color-primary-light:  #eff6ff;
  --color-primary-text:   #ffffff;

  /* Accent — green for actions / success */
  --color-accent:         #059669;
  --color-accent-hover:   #047857;
  --color-accent-light:   #dcfce7;

  /* Neutral — grays */
  --color-bg:             #f1f5f9;
  --color-surface:        #ffffff;
  --color-border:         #e2e5eb;
  --color-text:           #0f172a;
  --color-text-secondary: #64748b;
  --color-text-muted:     #94a3b8;

  /* Danger */
  --color-danger:         #dc2626;
  --color-danger-bg:      #fdecea;
  --color-danger-text:    #611a15;

  /* Warning */
  --color-warning-bg:     #fef3c7;
  --color-warning-text:   #92400e;

  /* Price accent */
  --color-price:          #059669;
  --color-price-bg:       #ecfdf5;

  /* Shadows — layered for depth */
  --shadow-sm:  0 1px 2px rgba(15, 23, 42, 0.04), 0 1px 3px rgba(15, 23, 42, 0.06);
  --shadow-md:  0 2px 4px rgba(15, 23, 42, 0.04), 0 6px 16px rgba(15, 23, 42, 0.08);
  --shadow-lg:  0 4px 6px rgba(15, 23, 42, 0.04), 0 12px 28px rgba(15, 23, 42, 0.12);
  --shadow-xl:  0 8px 16px rgba(15, 23, 42, 0.06), 0 24px 48px rgba(15, 23, 42, 0.14);

  /* Radius */
  --radius-sm:  8px;
  --radius-md:  12px;
  --radius-lg:  16px;
  --radius-xl:  20px;
  --radius-2xl: 24px;
  --radius-pill: 9999px;

  /* Transitions */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);

  /* Material color overrides */
  --mdc-filled-button-container-color: var(--color-primary);
  --mdc-filled-button-label-text-color: var(--color-primary-text);
}

/* ── Reset / Base ──────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
}
*:not(.material-icons){
 font-family: 'Poppins' !important;
}
html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: 'Poppins', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 0.9375rem;
  line-height: 1.6;
  background: var(--color-bg);
  color: var(--color-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ── Typography ────────────────────────────────────────────────────── */
h1, h2, h3, h4, h5, h6 {
  margin: 0;
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  line-height: 1.25;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

h1 { font-size: 1.85rem; font-weight: 700; }
h2 { font-size: 1.4rem;  font-weight: 700; }
h3 { font-size: 1.1rem;  font-weight: 600; }

p {
  margin: 0;
  line-height: 1.6;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* ── Layout Utilities ──────────────────────────────────────────────── */
.page-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ── Card ──────────────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  box-shadow: var(--shadow-md);
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.35s var(--ease-out), transform 0.35s var(--ease-out);
}

.card:hover {
  box-shadow: var(--shadow-lg);
}

/* ── Grid ──────────────────────────────────────────────────────────── */
.grid {
  display: grid;
  gap: 1.25rem;
}

@media (min-width: 768px) {
  .grid-2 {
    grid-template-columns: 270px 1fr;
  }
}

/* ── Skeleton Loader ───────────────────────────────────────────────── */
@keyframes shimmer {
  0%   { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

.skeleton {
  background: linear-gradient(90deg, #e2e8f0 25%, #cbd5e1 50%, #e2e8f0 75%);
  background-size: 800px 100%;
  animation: shimmer 1.6s ease-in-out infinite;
  border-radius: var(--radius-md);
}

.skeleton-text {
  height: 14px;
  margin-bottom: 8px;
  border-radius: 6px;
}

.skeleton-text--sm {
  width: 40%;
}

.skeleton-text--md {
  width: 70%;
}

.skeleton-text--lg {
  width: 90%;
}

/* ── Angular Material Global Overrides ─────────────────────────────── */

/* Toolbar uses our primary */
.mat-toolbar.mat-primary {
  background: var(--color-primary) !important;
  color: var(--color-primary-text) !important;
}

/* Override toolbar default sizing so component height wins */
.mat-toolbar {
  min-height: 0 !important;
  padding: 0 !important;
}

.mat-toolbar-row,
.mat-toolbar-single-row {
  height: auto !important;
  min-height: 0 !important;
  padding: 0 !important;
}

/* Form fields — outline appearance with our border tokens */
.mat-mdc-form-field {
  width: 100%;
  max-width: 100%;
  font-family: inherit;
  box-sizing: border-box;
}

/* ── Compact form-field: consistent 40px height ───────────────────── */
.mat-mdc-form-field .mat-mdc-text-field-wrapper {
  padding: 0 0.65rem;
}

.mat-mdc-form-field .mat-mdc-form-field-infix {
  min-height: 40px;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  display: flex;
  align-items: center;
}

.mat-mdc-form-field .mdc-text-field {
  padding: 0 0.65rem;
  height: 40px;
}

.mat-mdc-form-field .mat-mdc-floating-label {
  font-size: 0.85rem;
  top: 20px !important;   /* vertically center when not floating */
}

.mat-mdc-form-field input.mat-mdc-input-element {
  font-size: 0.875rem;    /* ~14px */
  line-height: 1.4;
}

.mat-mdc-form-field textarea.mat-mdc-input-element {
  font-size: 0.875rem;
}

.mat-mdc-select {
  font-size: 0.875rem;
}

.mat-mdc-select-trigger {
  height: 100%;
  display: flex;
  align-items: center;
}

/* Ensure prefix / suffix icons are vertically centred */
.mat-mdc-form-field .mat-mdc-form-field-icon-prefix,
.mat-mdc-form-field .mat-mdc-form-field-icon-suffix {
  display: flex;
  align-items: center;
  padding: 0 4px 0 0;
}

.mat-mdc-form-field .mat-mdc-form-field-icon-prefix > mat-icon,
.mat-mdc-form-field .mat-mdc-form-field-icon-suffix > mat-icon,
.mat-mdc-form-field [matPrefix],
.mat-mdc-form-field [matSuffix] {
  font-size: 18px;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
}

/* Remove bottom subscript gap when there's no error/hint */
.mat-mdc-form-field-subscript-wrapper {
  margin-bottom: 0 !important;
}

/* Ensure form fields never exceed their parent */
.mat-mdc-form-field {
  width: 100%;
  font-family: inherit;
  max-width: 100%;
  box-sizing: border-box;
}
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__leading,
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__notch,
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__trailing {
  border-color: var(--color-border);
}

.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__leading,
.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__notch,
.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__trailing {
  border-color: var(--color-primary) !important;
}

/* Raised buttons use our primary */
.mat-mdc-raised-button.mat-primary {
  --mdc-filled-button-container-color: var(--color-primary);
  --mdc-filled-button-label-text-color: var(--color-primary-text);
  border-radius: var(--radius-md) !important;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.mat-mdc-raised-button.mat-primary:hover {
  --mdc-filled-button-container-color: var(--color-primary-hover);
}

/* Mat card — inherit our surface + shadow tokens */
.mat-mdc-card {
  --mdc-elevated-card-container-color: var(--color-surface);
  border-radius: var(--radius-lg) !important;
  box-shadow: var(--shadow-md) !important;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

/* Chips use our design tokens */
.mat-mdc-chip.mat-mdc-standard-chip {
  font-size: 0.75rem;
  font-weight: 500;
  --mdc-chip-container-shape-radius: var(--radius-pill);
  height: auto;
  min-height: 28px;
}

/* Checkbox primary color */
.mat-mdc-checkbox.mat-primary {
  --mdc-checkbox-selected-checkmark-color: #fff;
  --mdc-checkbox-selected-icon-color: var(--color-primary);
  --mdc-checkbox-selected-hover-icon-color: var(--color-primary-hover);
}

/* Spinner uses our primary */
.mat-mdc-progress-spinner {
  --mdc-circular-progress-active-indicator-color: var(--color-primary);
}

/* Select panel — ensure it uses our surface */
.mat-mdc-select-panel {
  background: var(--color-surface);
}

/* Stroked buttons */
.mat-mdc-outlined-button,
.mdc-button--outlined {
  border-radius: var(--radius-md) !important;
}

/* ── Global spacing utilities ──────────────────────────────────────── */
.section-gap   { margin-bottom: 1.5rem; }
.section-gap-sm { margin-bottom: 1rem; }

/* Smooth page-level scroll on desktop */
@media (min-width: 768px) {
  html, body { overflow-x: hidden; }
}

/* ── Angular Material Theme ─────────────────────────────────────────── */
@import '@angular/material/prebuilt-themes/indigo-pink.css';

/* ── Design Tokens (CSS Custom Properties) ─────────────────────────── */
:root {
  /* Primary — deep blue */
  --color-primary:        #1e3a8a;
  --color-primary-hover:  #172e6e;
  --color-primary-light:  #eff6ff;
  --color-primary-text:   #ffffff;

  /* Accent — green for actions / success */
  --color-accent:         #059669;
  --color-accent-hover:   #047857;
  --color-accent-light:   #dcfce7;

  /* Neutral — grays */
  --color-bg:             #f1f5f9;
  --color-surface:        #ffffff;
  --color-border:         #e2e5eb;
  --color-text:           #0f172a;
  --color-text-secondary: #64748b;
  --color-text-muted:     #94a3b8;

  /* Danger */
  --color-danger:         #dc2626;
  --color-danger-bg:      #fdecea;
  --color-danger-text:    #611a15;

  /* Warning */
  --color-warning-bg:     #fef3c7;
  --color-warning-text:   #92400e;

  /* Price accent */
  --color-price:          #059669;
  --color-price-bg:       #ecfdf5;

  /* Shadows — layered for depth */
  --shadow-sm:  0 1px 2px rgba(15, 23, 42, 0.04), 0 1px 3px rgba(15, 23, 42, 0.06);
  --shadow-md:  0 2px 4px rgba(15, 23, 42, 0.04), 0 6px 16px rgba(15, 23, 42, 0.08);
  --shadow-lg:  0 4px 6px rgba(15, 23, 42, 0.04), 0 12px 28px rgba(15, 23, 42, 0.12);
  --shadow-xl:  0 8px 16px rgba(15, 23, 42, 0.06), 0 24px 48px rgba(15, 23, 42, 0.14);

  /* Radius */
  --radius-sm:  8px;
  --radius-md:  12px;
  --radius-lg:  16px;
  --radius-xl:  20px;
  --radius-2xl: 24px;
  --radius-pill: 9999px;

  /* Transitions */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);

  /* Material color overrides */
  --mdc-filled-button-container-color: var(--color-primary);
  --mdc-filled-button-label-text-color: var(--color-primary-text);
}

/* ── Reset / Base ──────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
}
*:not(.material-icons){
 font-family: 'Poppins' !important;
}
html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: 'Poppins', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 0.9375rem;
  line-height: 1.6;
  background: var(--color-bg);
  color: var(--color-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ── Typography ────────────────────────────────────────────────────── */
h1, h2, h3, h4, h5, h6 {
  margin: 0;
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  line-height: 1.25;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

h1 { font-size: 1.85rem; font-weight: 700; }
h2 { font-size: 1.4rem;  font-weight: 700; }
h3 { font-size: 1.1rem;  font-weight: 600; }

p {
  margin: 0;
  line-height: 1.6;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* ── Layout Utilities ──────────────────────────────────────────────── */
.page-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ── Card ──────────────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  box-shadow: var(--shadow-md);
  border: 1px solid rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.35s var(--ease-out), transform 0.35s var(--ease-out);
}

.card:hover {
  box-shadow: var(--shadow-lg);
}

/* ── Grid ──────────────────────────────────────────────────────────── */
.grid {
  display: grid;
  gap: 1.25rem;
}

@media (min-width: 768px) {
  .grid-2 {
    grid-template-columns: 270px 1fr;
  }
}

/* ── Skeleton Loader ───────────────────────────────────────────────── */
@keyframes shimmer {
  0%   { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

.skeleton {
  background: linear-gradient(90deg, #e2e8f0 25%, #cbd5e1 50%, #e2e8f0 75%);
  background-size: 800px 100%;
  animation: shimmer 1.6s ease-in-out infinite;
  border-radius: var(--radius-md);
}

.skeleton-text {
  height: 14px;
  margin-bottom: 8px;
  border-radius: 6px;
}

.skeleton-text--sm {
  width: 40%;
}

.skeleton-text--md {
  width: 70%;
}

.skeleton-text--lg {
  width: 90%;
}

/* ── Angular Material Global Overrides ─────────────────────────────── */

/* Toolbar uses our primary */
.mat-toolbar.mat-primary {
  background: var(--color-primary) !important;
  color: var(--color-primary-text) !important;
}

/* Override toolbar default sizing so component height wins */
.mat-toolbar {
  min-height: 0 !important;
  padding: 0 !important;
}

.mat-toolbar-row,
.mat-toolbar-single-row {
  height: auto !important;
  min-height: 0 !important;
  padding: 0 !important;
}

/* Form fields — outline appearance with our border tokens */
.mat-mdc-form-field {
  width: 100%;
  max-width: 100%;
  font-family: inherit;
  box-sizing: border-box;
}

/* ── Compact form-field: consistent 40px height ───────────────────── */
.mat-mdc-form-field .mat-mdc-text-field-wrapper {
  padding: 0 0.65rem;
}

.mat-mdc-form-field .mat-mdc-form-field-infix {
  min-height: 40px;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  display: flex;
  align-items: center;
}

.mat-mdc-form-field .mdc-text-field {
  padding: 0 0.65rem;
  height: 40px;
}

.mat-mdc-form-field .mat-mdc-floating-label {
  font-size: 0.85rem;
  top: 20px !important;   /* vertically center when not floating */
}

.mat-mdc-form-field input.mat-mdc-input-element {
  font-size: 0.875rem;    /* ~14px */
  line-height: 1.4;
}

.mat-mdc-form-field textarea.mat-mdc-input-element {
  font-size: 0.875rem;
}

.mat-mdc-select {
  font-size: 0.875rem;
}

.mat-mdc-select-trigger {
  height: 100%;
  display: flex;
  align-items: center;
}

/* Ensure prefix / suffix icons are vertically centred */
.mat-mdc-form-field .mat-mdc-form-field-icon-prefix,
.mat-mdc-form-field .mat-mdc-form-field-icon-suffix {
  display: flex;
  align-items: center;
  padding: 0 4px 0 0;
}

.mat-mdc-form-field .mat-mdc-form-field-icon-prefix > mat-icon,
.mat-mdc-form-field .mat-mdc-form-field-icon-suffix > mat-icon,
.mat-mdc-form-field [matPrefix],
.mat-mdc-form-field [matSuffix] {
  font-size: 18px;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
}

/* Remove bottom subscript gap when there's no error/hint */
.mat-mdc-form-field-subscript-wrapper {
  margin-bottom: 0 !important;
}

/* Outline border tokens */
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__leading,
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__notch,
.mat-mdc-form-field .mdc-text-field--outlined .mdc-notched-outline__trailing {
  border-color: var(--color-border);
}

.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__leading,
.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__notch,
.mat-mdc-form-field.mat-focused .mdc-text-field--outlined .mdc-notched-outline__trailing {
  border-color: var(--color-primary) !important;
}

/* Raised buttons use our primary */
.mat-mdc-raised-button.mat-primary {
  --mdc-filled-button-container-color: var(--color-primary);
  --mdc-filled-button-label-text-color: var(--color-primary-text);
  border-radius: var(--radius-md) !important;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.mat-mdc-raised-button.mat-primary:hover {
  --mdc-filled-button-container-color: var(--color-primary-hover);
}

/* Mat card — inherit our surface + shadow tokens */
.mat-mdc-card {
  --mdc-elevated-card-container-color: var(--color-surface);
  border-radius: var(--radius-lg) !important;
  box-shadow: var(--shadow-md) !important;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

/* Chips use our design tokens */
.mat-mdc-chip.mat-mdc-standard-chip {
  font-size: 0.75rem;
  font-weight: 500;
  --mdc-chip-container-shape-radius: var(--radius-pill);
  height: auto;
  min-height: 28px;
}

/* Checkbox primary color */
.mat-mdc-checkbox.mat-primary {
  --mdc-checkbox-selected-checkmark-color: #fff;
  --mdc-checkbox-selected-icon-color: var(--color-primary);
  --mdc-checkbox-selected-hover-icon-color: var(--color-primary-hover);
}

/* Spinner uses our primary */
.mat-mdc-progress-spinner {
  --mdc-circular-progress-active-indicator-color: var(--color-primary);
}

/* Select panel — ensure it uses our surface */
.mat-mdc-select-panel {
  background: var(--color-surface);
}

/* Stroked buttons */
.mat-mdc-outlined-button,
.mdc-button--outlined {
  border-radius: var(--radius-md) !important;
}

/* ── Global spacing utilities ──────────────────────────────────────── */
.section-gap   { margin-bottom: 1.5rem; }
.section-gap-sm { margin-bottom: 1rem; }

/* Smooth page-level scroll on desktop */
@media (min-width: 768px) {
  html, body { overflow-x: hidden; }
}

.create-page {
  padding-top: 1.5rem;
  padding-bottom: 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.back-btn {
  width: fit-content;
}

.form-card {
  max-width: 740px;
  border-radius: var(--radius-lg, 16px) !important;
}

.form-card h2 {
  margin: 0 0 1.5rem;
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

/* Fieldsets */
fieldset {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg, 16px);
  padding: 1.25rem 1.35rem;
  margin: 0 0 1.5rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

fieldset:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(30, 58, 138, 0.08);
}

legend {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--color-text);
  padding: 0 0.5rem;
}

/* Field rows */
.field-row {
  display: grid;
  gap: 1rem;
}

@media (min-width: 600px) {
  .field-row {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  }
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.85rem;
}

.full-width {
  width: 100%;
}

.field-error {
  font-size: 0.78rem;
  color: var(--color-danger);
}

/* Banners */
.error-banner {
  background: var(--color-danger-bg);
  color: var(--color-danger-text);
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md, 12px);
  margin-bottom: 0.65rem;
  font-size: 0.88rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.success-banner {
  background: var(--color-accent-light);
  color: #166534;
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md, 12px);
  margin-bottom: 0.65rem;
  font-size: 0.88rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: fadeIn 0.3s var(--ease-out, ease);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Submit */
.submit-btn {
  width: 100%;
  padding: 0.85rem !important;
  font-size: 1.02rem !important;
  border-radius: var(--radius-md, 12px) !important;
}

/* ── Page layout — centered form ───────────────────────────────────── */
.create-page {
  padding-top: 1.5rem;
  padding-bottom: 3rem;
  display: flex;
  flex-direction: column;
  align-items: center;                 /* center the card horizontally */
  gap: 1rem;
}

/* Back button — left-aligned within the centered container */
.back-btn {
  align-self: flex-start;
  max-width: 860px;
  width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.92rem;
  cursor: pointer;
  transition: color 0.2s ease, gap 0.2s ease;
}

.back-btn:hover {
  color: var(--color-primary-hover);
  gap: 0.5rem;
}

/* ── Form card — centered with shadow ─────────────────────────────── */
.form-card {
  width: 100%;
  max-width: 860px;
  margin: 0 auto;                      /* centered horizontally */
  border-radius: var(--radius-xl, 20px) !important;
  box-shadow: 0 4px 6px rgba(15, 23, 42, 0.03),
              0 12px 32px rgba(15, 23, 42, 0.08) !important;
  border: 1px solid rgba(0, 0, 0, 0.04);
  overflow: hidden;
}

/* Card content — generous inner padding */
.form-card .mat-mdc-card-content {
  padding: 2.25rem 2.5rem 2rem !important;
}

/* Page heading */
.form-card h2 {
  margin: 0 0 1.75rem;
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--color-text);
  text-align: center;
}

/* ── Fieldsets — distinct sections with spacing ───────────────────── */
fieldset {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg, 16px);
  padding: 1.5rem 1.75rem 1.25rem;
  margin: 0 0 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

fieldset:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(30, 58, 138, 0.08);
}

legend {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--color-text);
  padding: 0 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

/* ── Field rows — responsive grid ─────────────────────────────────── */
.field-row {
  display: grid;
  gap: 0.85rem;
}

@media (min-width: 600px) {
  .field-row {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 1rem;
  }
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.5rem;
}

.full-width {
  width: 100%;
}

/* Hide subscript spacer on form fields to tighten vertical spacing */
fieldset .mat-mdc-form-field-subscript-wrapper:not(.mat-mdc-form-field-error-wrapper) {
  margin-bottom: 0 !important;
}

.field-error {
  font-size: 0.78rem;
  color: var(--color-danger);
  margin-top: 0.1rem;
}

/* ── Banners ──────────────────────────────────────────────────────── */
.error-banner {
  background: var(--color-danger-bg);
  color: var(--color-danger-text);
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md, 12px);
  margin-bottom: 0.85rem;
  font-size: 0.88rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.success-banner {
  background: var(--color-accent-light);
  color: #166534;
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md, 12px);
  margin-bottom: 0.85rem;
  font-size: 0.88rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: fadeIn 0.3s var(--ease-out, ease);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Submit button ────────────────────────────────────────────────── */
.submit-btn {
  width: 100%;
  padding: 0.85rem !important;
  font-size: 1.02rem !important;
  font-weight: 700 !important;
  border-radius: var(--radius-md, 12px) !important;
  margin-top: 0.5rem;
  transition: background 0.2s ease, transform 0.15s ease;
}

.submit-btn:not(:disabled):hover {
  transform: translateY(-1px);
}

/* ── Responsive — tighten on mobile ───────────────────────────────── */
@media (max-width: 600px) {
  .create-page {
    padding-top: 1rem;
    padding-bottom: 2rem;
    gap: 0.75rem;
  }

  .form-card .mat-mdc-card-content {
    padding: 1.25rem 1.15rem 1rem !important;
  }

  .form-card h2 {
    font-size: 1.3rem;
    margin-bottom: 1.25rem;
  }

  fieldset {
    padding: 1rem 1rem 0.85rem;
    margin-bottom: 1.25rem;
  }

  .field-row {
    grid-template-columns: 1fr;         /* stack all fields on mobile */
  }

  .submit-btn {
    font-size: 0.95rem !important;
  }
}

import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { TenantService } from '../../../../services/tenant.service';
import { AuthService } from '../../../../services/auth.service';
import { CreateTenantPostRequest } from '../../../../models/tenant.model';
import { ResolvedLocation } from '../../../../models/location.model';

@Component({
  selector: 'app-tenant-create-post',
  templateUrl: './tenant-create-post.component.html',
  styleUrls: ['./tenant-create-post.component.css']
})
export class TenantCreatePostComponent implements OnInit {

  form: FormGroup;
  loading = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;

  readonly foodOptions = ['VEG', 'NON_VEG', 'BOTH'];
  readonly smokingOptions = ['NO_SMOKING', 'SMOKING_ALLOWED'];
  readonly genderOptions = ['MALE', 'FEMALE', 'ANY'];

  constructor(
    private readonly fb: FormBuilder,
    private readonly tenantService: TenantService,
    private readonly router: Router,
    private readonly authService: AuthService
  ) {
    const today = new Date().toISOString().split('T')[0];

    this.form = this.fb.group({
      // User
      fullName:    ['', [Validators.required, Validators.maxLength(100)]],
      email:       ['', [Validators.required, Validators.email, Validators.maxLength(120)]],
      phoneNumber: ['', [Validators.maxLength(20)]],

      // Post
      title:              ['', [Validators.required, Validators.maxLength(120)]],
      description:        ['', [Validators.maxLength(500)]],
      minBudget:          [null, [Validators.required, Validators.min(1)]],
      maxBudget:          [null, [Validators.required, Validators.min(1)]],
      totalCapacity:      [null, [Validators.required, Validators.min(1)]],
      currentOccupancy:   [null, [Validators.required, Validators.min(0)]],
      preferredLatitude:  [null, [Validators.required, Validators.min(-90), Validators.max(90)]],
      preferredLongitude: [null, [Validators.required, Validators.min(-180), Validators.max(180)]],
      locationLabel:      ['', [Validators.required, Validators.maxLength(120)]],
      moveInDate:         [today, [Validators.required]],

      // Preferences
      foodPreference:    [''],
      smokingPreference: [''],
      preferredGender:   [''],
      additionalNotes:   ['', [Validators.maxLength(300)]]
    });
  }

  ngOnInit(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      this.form.patchValue({ email: user.email });
    }
  }

  /**
   * Called by the location picker when a location is resolved (GPS or city).
   * Auto-fills lat, lng, and locationLabel from the reverse-geocoded address.
   */
  onLocationSelected(location: ResolvedLocation | null): void {
    if (location) {
      this.form.patchValue({
        preferredLatitude: location.latitude,
        preferredLongitude: location.longitude,
        locationLabel: location.address || location.label
      });
    } else {
      this.form.patchValue({
        preferredLatitude: null,
        preferredLongitude: null,
        locationLabel: ''
      });
    }
  }

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.value;

    // Validate maxBudget >= minBudget
    if (v.maxBudget < v.minBudget) {
      this.errorMessage = 'Max budget must be greater than or equal to min budget.';
      return;
    }

    // Validate capacity
    if (v.currentOccupancy > v.totalCapacity) {
      this.errorMessage = 'Current occupancy cannot exceed total capacity.';
      return;
    }

    const request: CreateTenantPostRequest = {
      user: {
        fullName: v.fullName,
        email: v.email,
        phoneNumber: v.phoneNumber || undefined
      },
      title: v.title,
      description: v.description || undefined,
      minBudget: v.minBudget,
      maxBudget: v.maxBudget,
      totalCapacity: v.totalCapacity,
      currentOccupancy: v.currentOccupancy,
      preferredLatitude: v.preferredLatitude,
      preferredLongitude: v.preferredLongitude,
      locationLabel: v.locationLabel,
      moveInDate: v.moveInDate,
      preference: {
        foodPreference: v.foodPreference || undefined,
        smokingPreference: v.smokingPreference || undefined,
        preferredGender: v.preferredGender || undefined,
        additionalNotes: v.additionalNotes || undefined
      }
    };

    this.loading = true;
    this.errorMessage = null;
    this.successMessage = null;

    this.tenantService.createTenantPost(request).subscribe({
      next: () => {
        this.successMessage = 'Room posted successfully! Redirecting…';
        this.loading = false;
        setTimeout(() => this.router.navigate(['/tenant-matching']), 1500);
      },
      error: (err) => {
        this.errorMessage = err.error?.message ?? 'Failed to post room. Please try again.';
        this.loading = false;
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/tenant-matching']);
  }

  /** Helper for template — check if a field is invalid and touched. */
  isInvalid(field: string): boolean {
    const ctrl = this.form.get(field);
    return !!(ctrl && ctrl.invalid && ctrl.touched);
  }
}

import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { TenantService } from '../../../../services/tenant.service';
import { AuthService } from '../../../../services/auth.service';
import { CreateTenantPostRequest } from '../../../../models/tenant.model';
import { ResolvedLocation } from '../../../../models/location.model';

@Component({
  selector: 'app-tenant-create-post',
  templateUrl: './tenant-create-post.component.html',
  styleUrls: ['./tenant-create-post.component.css']
})
export class TenantCreatePostComponent implements OnInit {

  form: FormGroup;
  loading = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;

  readonly foodOptions = ['VEG', 'NON_VEG', 'BOTH'];
  readonly smokingOptions = ['NO_SMOKING', 'SMOKING_ALLOWED'];
  readonly genderOptions = ['MALE', 'FEMALE', 'ANY'];

  constructor(
    private readonly fb: FormBuilder,
    private readonly tenantService: TenantService,
    private readonly router: Router,
    private readonly authService: AuthService
  ) {
    const today = new Date().toISOString().split('T')[0];

    this.form = this.fb.group({
      // User
      fullName:    ['', [Validators.required, Validators.maxLength(100)]],
      email:       ['', [Validators.required, Validators.email, Validators.maxLength(120)]],
      phoneNumber: ['', [Validators.maxLength(20)]],

      // Post
      title:              ['', [Validators.required, Validators.maxLength(120)]],
      description:        ['', [Validators.maxLength(500)]],
      minBudget:          [null, [Validators.required, Validators.min(1)]],
      maxBudget:          [null, [Validators.required, Validators.min(1)]],
      totalCapacity:      [null, [Validators.required, Validators.min(1)]],
      currentOccupancy:   [null, [Validators.required, Validators.min(0)]],
      preferredLatitude:  [null, [Validators.required, Validators.min(-90), Validators.max(90)]],
      preferredLongitude: [null, [Validators.required, Validators.min(-180), Validators.max(180)]],
      locationLabel:      ['', [Validators.required, Validators.maxLength(120)]],
      moveInDate:         [today, [Validators.required]],

      // Preferences
      foodPreference:    [''],
      smokingPreference: [''],
      preferredGender:   [''],
      additionalNotes:   ['', [Validators.maxLength(300)]]
    });
  }

  ngOnInit(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      this.form.patchValue({
        fullName: user.fullName || '',
        email: user.email,
        phoneNumber: user.phoneNumber || ''
      });
    }
  }

  /**
   * Called by the location picker when a location is resolved (GPS or city).
   * Auto-fills lat, lng, and locationLabel from the reverse-geocoded address.
   */
  onLocationSelected(location: ResolvedLocation | null): void {
    if (location) {
      this.form.patchValue({
        preferredLatitude: location.latitude,
        preferredLongitude: location.longitude,
        locationLabel: location.address || location.label
      });
    } else {
      this.form.patchValue({
        preferredLatitude: null,
        preferredLongitude: null,
        locationLabel: ''
      });
    }
  }

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.value;

    // Validate maxBudget >= minBudget
    if (v.maxBudget < v.minBudget) {
      this.errorMessage = 'Max budget must be greater than or equal to min budget.';
      return;
    }

    // Validate capacity
    if (v.currentOccupancy > v.totalCapacity) {
      this.errorMessage = 'Current occupancy cannot exceed total capacity.';
      return;
    }

    const request: CreateTenantPostRequest = {
      user: {
        fullName: v.fullName,
        email: v.email,
        phoneNumber: v.phoneNumber || undefined
      },
      title: v.title,
      description: v.description || undefined,
      minBudget: v.minBudget,
      maxBudget: v.maxBudget,
      totalCapacity: v.totalCapacity,
      currentOccupancy: v.currentOccupancy,
      preferredLatitude: v.preferredLatitude,
      preferredLongitude: v.preferredLongitude,
      locationLabel: v.locationLabel,
      moveInDate: v.moveInDate,
      preference: {
        foodPreference: v.foodPreference || undefined,
        smokingPreference: v.smokingPreference || undefined,
        preferredGender: v.preferredGender || undefined,
        additionalNotes: v.additionalNotes || undefined
      }
    };

    this.loading = true;
    this.errorMessage = null;
    this.successMessage = null;

    this.tenantService.createTenantPost(request).subscribe({
      next: () => {
        this.successMessage = 'Room posted successfully! Redirecting…';
        this.loading = false;
        setTimeout(() => this.router.navigate(['/tenant-matching']), 1500);
      },
      error: (err) => {
        this.errorMessage = err.error?.message ?? 'Failed to post room. Please try again.';
        this.loading = false;
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/tenant-matching']);
  }

  /** Helper for template — check if a field is invalid and touched. */
  isInvalid(field: string): boolean {
    const ctrl = this.form.get(field);
    return !!(ctrl && ctrl.invalid && ctrl.touched);
  }
}

